preConditionHook:
// THE DAY-TYPE READ. The session's opening-range height as a fraction of the
// recent average daily range, tested against a band. Under about 0.3 the day
// is "in breakout mode"; a third to a half favours a trending trading range
// day; above about a half the opening move was a spike and the day is likely
// spike-and-channel.
//
// ONE RULE FOR ALL FOUR READINGS. Eight mined candidates say the same thing
// at four thresholds -- about 25 percent, under 30 percent, a third to a
// half, and "large" -- so the rule is a low/high fraction BAND and each
// reading is a setting of it. The "large opening range" form is this rule
// with lowFraction raised (or the band negated by the per-placement toggle),
// not a second rule. Defaults 0.0 / 0.3, the breakout-mode reading. The
// spike-DIRECTION and climactic-reversal terms two of the candidates add are
// separate concerns and are not carried.
//
// Both primitives are INLINED, as the corpus does with named composites:
// SessionOpeningRange fixes orHeight and AverageDailyRange fixes adr; neither
// file is referenced and the blocks are the same text.
//
// SESSION MODEL, per the standing decision: the twin's date > date[1],
// mirrored as day_of(ctx.Time(0)) > day_of(ctx.Time(1)); barsIn is 1 on the
// session's first bar. The average-daily-range scan skips bars carrying the
// current date, so today's incomplete session is never in the average, and
// its dayLookback guard WRAPS the date read because EasyLanguage does not
// short-circuit and the twins must touch the same history. Deepest index
// maxScanBars + 1; maxScanBars must cover dayLookback sessions of bars.
//
// Direction-agnostic, so both sides are identical text. Intraday bars only.
if (day_of(ctx.Time(0)) > day_of(ctx.Time(1))) {
    barsIn = 1;
    orHigh = high[0];
    orLow = low[0];
} else {
    barsIn = barsIn + 1;
    if (barsIn <= (int)openingBars) {
        if (el_gt(high[0], orHigh)) orHigh = high[0];
        if (el_lt(low[0], orLow)) orLow = low[0];
    }
}
orHeight = orHigh - orLow;
orSet = el_ge((double)barsIn, openingBars);
adrSum = 0.0;
adrDays = 0;
dHi = 0.0;
dLo = 0.0;
dOpen = false;
for (int kk = 1; kk <= (int)maxScanBars; ++kk) {
    if (el_lt((double)adrDays, dayLookback)) {
        if (day_of(ctx.Time(kk)) != day_of(ctx.Time(0))) {
            if (!dOpen) {
                dHi = high[kk];
                dLo = low[kk];
                dOpen = true;
            } else {
                if (el_gt(high[kk], dHi)) dHi = high[kk];
                if (el_lt(low[kk], dLo)) dLo = low[kk];
            }
            if (day_of(ctx.Time(kk + 1)) != day_of(ctx.Time(kk))) {
                adrSum = adrSum + (dHi - dLo);
                adrDays = adrDays + 1;
                dOpen = false;
            }
        }
    }
}
adrReady = el_ge((double)adrDays, dayLookback);
if (adrReady) {
    adr = adrSum / dayLookback;
} else {
    adr = 0.0;
}
